 public static SportsChaosWeather Weather(SportsEventSession m,string folder){
  var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/WeatherMaker/Prefab/WeatherMakerPrefab.prefab");var world=(GameObject)PrefabUtility.InstantiatePrefab(prefab);PrefabUtility.UnpackPrefabInstance(world,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);world.name=folder+" scene-owned Weather Maker";var w=m.gameObject.AddComponent<SportsChaosWeather>();w.session=m;w.vendor=world.GetComponentInChildren<WeatherMakerScript>(true);w.vendor.IsPermanent=false;w.precipitation=world.GetComponentInChildren<WeatherMakerPrecipitationManagerScript>(true);w.wind=world.GetComponentInChildren<WeatherMakerWindScript>(true);w.sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsInactive.Include).First(l=>l.type==LightType.Directional);w.clouds=world.GetComponentInChildren<WeatherMakerFullScreenCloudsScript>(true);w.cloudProfiles=CloudProfiles(folder,false);w.vendor.AutoFindMainCamera=false;w.vendor.AllowCameras.Clear();foreach(var c in m.cameras)w.vendor.AllowCameras.Add(c);
  w.vendor.ResourceContainer=AssetDatabase.LoadAssetAtPath<WeatherMakerResourceContainerScript>("Assets/TruckBaseJumping/Materials/Base weather resources.asset");var wind=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<WeatherMakerWindProfileScript>("Assets/TruckBaseJumping/Materials/Shared wind profile.asset"));wind.name=folder+" wind";string path="Assets/"+folder+"/Materials/Shared chaos wind.asset";var owned=AssetDatabase.LoadAssetAtPath<WeatherMakerWindProfileScript>(path);if(owned==null){AssetDatabase.CreateAsset(wind,path);owned=wind;}else{EditorUtility.CopySerialized(wind,owned);UnityEngine.Object.DestroyImmediate(wind);}w.wind.WindProfile=owned;
  world.GetComponentInChildren<WeatherMakerDayNightCycleManagerScript>(true).DayNightProfile=AssetDatabase.LoadAssetAtPath<WeatherMakerDayNightCycleProfileScript>("Assets/TruckBaseJumping/Materials/Fixed daylight.asset");
  var rendering=m.gameObject.AddComponent<LWS.TruckBaseJumping.BaseJumpRendering>();rendering.pipeline=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/TruckBaseJumping/Rendering/Base pipeline.asset");
  w.ambience=m.gameObject.AddComponent<AudioSource>();w.ambience.clip=AssetDatabase.FindAssets("t:AudioClip",new[]{"Assets/WeatherMaker/Prefab/Sound"}).Select(AssetDatabase.GUIDToAssetPath).Where(p=>p.IndexOf("Wind",StringComparison.OrdinalIgnoreCase)>=0).Select(AssetDatabase.LoadAssetAtPath<AudioClip>).FirstOrDefault();w.ambience.loop=true;w.ambience.playOnAwake=false;return w;
 }
 public static WeatherMakerCloudProfileScript[] CloudProfiles(string folder,bool low){var result=new WeatherMakerCloudProfileScript[3];string[] names={"LightScattered","StormMultiLayer","HeavyBright"};for(int i=0;i<3;i++){string path="Assets/"+folder+"/Materials/Cloud presentation "+i+".asset";var owned=AssetDatabase.LoadAssetAtPath<WeatherMakerCloudProfileScript>(path);if(owned==null){owned=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<WeatherMakerCloudProfileScript>("Assets/WeatherMaker/Prefab/Profiles/Clouds/Profiles/WeatherMakerCloudProfile_"+names[i]+".asset"));owned.name=folder+" scoped cloud "+i;if(low){owned.CloudHeight.Minimum=owned.CloudHeight.Maximum=155;owned.CloudHeightTop.Minimum=owned.CloudHeightTop.Maximum=193;}AssetDatabase.CreateAsset(owned,path);}result[i]=owned;}return result;}
 public static Material Flare(string folder){string path="Assets/"+folder+"/Materials/Transparent comic flare.mat";var material=AssetDatabase.LoadAssetAtPath<Material>(path);if(material==null){material=new Material(AssetDatabase.LoadAssetAtPath<Material>("Assets/NWH/Vehicle Physics 2/Effects/Materials/DustCloud.mat"));AssetDatabase.CreateAsset(material,path);}material.shader=Shader.Find("Universal Render Pipeline/Particles/Unlit");var texture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/WeatherMaker/Prefab/Textures/Flare/WeatherMakerFlare1.png");material.SetTexture("_BaseMap",texture);material.SetTexture("_MainTex",texture);material.SetColor("_BaseColor",Color.white);material.SetFloat("_Surface",1);material.SetFloat("_Blend",2);material.SetInt("_SrcBlend",(int)BlendMode.SrcAlpha);material.SetInt("_DstBlend",(int)BlendMode.One);material.SetInt("_ZWrite",0);material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");material.SetOverrideTag("RenderType","Transparent");material.renderQueue=3000;EditorUtility.SetDirty(material);return material;}
 public static void FixBlast(ParticleSystem system,Material material){system.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=system.main;main.loop=false;main.playOnAwake=false;main.startLifetime=new ParticleSystem.MinMaxCurve(.18f,.48f);main.startSpeed=new ParticleSystem.MinMaxCurve(5,13);main.startSize=new ParticleSystem.MinMaxCurve(1.4f,3.4f);main.maxParticles=64;main.startColor=new ParticleSystem.MinMaxGradient(new Color(1,.2f,.025f,.8f),new Color(1,.8f,.2f,.8f));var over=system.colorOverLifetime;over.enabled=true;var gradient=new Gradient();gradient.SetKeys(new[]{new GradientColorKey(Color.white,0),new GradientColorKey(new Color(1,.35f,.04f),1)},new[]{new GradientAlphaKey(.8f,0),new GradientAlphaKey(0,1)});over.color=gradient;var emission=system.emission;emission.rateOverTime=0;emission.SetBursts(new[]{new ParticleSystem.Burst(0,48)});var r=system.GetComponent<ParticleSystemRenderer>();r.sharedMaterial=material;r.shadowCastingMode=ShadowCastingMode.Off;}
 // Render-only reuse of the canonical Truck Taxi NWH/GR3D cockpit. No Taxi controllers or physics are instantiated.
 public static void Cab(Camera camera,string folder,int view,int layerBase=26){var existing=camera.transform.Find("Driver seat interior");if(existing!=null)UnityEngine.Object.DestroyImmediate(existing.gameObject);var root=new GameObject("Driver seat interior");root.transform.SetParent(camera.transform,false);var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/LWS/TruckTaxi/Prefabs/TruckTaxi_InterstateTractor.prefab");if(source==null)throw new Exception("Canonical Truck Taxi cab is required");var driver=source.GetComponentsInChildren<Camera>(true).First(c=>c.name=="Vehicle Camera Driver");var steering=root.AddComponent<SportsCabSteering>();camera.GetComponent<SportsEventCamera>().cabSteering=steering;const float scale=.62f;foreach(var filter in source.GetComponentsInChildren<MeshFilter>(true)){if(filter.name!="Cab"&&filter.name!="interior"&&filter.name!="steering wheel"&&filter.name!="door rt"&&filter.name!="doors lft")continue;var renderer=filter.GetComponent<MeshRenderer>();if(renderer==null)continue;var part=new GameObject("Taxi cockpit · "+filter.name);part.transform.SetParent(root.transform,false);part.transform.localPosition=(source.transform.InverseTransformPoint(filter.transform.position)-source.transform.InverseTransformPoint(driver.transform.position))*scale;part.transform.localRotation=Quaternion.Inverse(source.transform.rotation)*filter.transform.rotation;part.transform.localScale=filter.transform.lossyScale*scale;if(filter.name=="steering wheel")steering.wheel=part.transform;part.AddComponent<MeshFilter>().sharedMesh=filter.sharedMesh;var ownedRenderer=part.AddComponent<MeshRenderer>();ownedRenderer.sharedMaterials=renderer.sharedMaterials;ownedRenderer.shadowCastingMode=ShadowCastingMode.Off;ownedRenderer.receiveShadows=false;part.layer=layerBase+view;}root.layer=layerBase+view;camera.nearClipPlane=.025f;
 }
}
